import{_ as t,o as s,c as o,a2 as i}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-022 — Science links: at most five per panel, curated per body, ranked per mission","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-022-science-link-lists.md","filePath":"uxs/decisions/UXD-022-science-link-lists.md"}'),a={name:"uxs/decisions/UXD-022-science-link-lists.md"};function n(c,e,r,d,l,h){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="uxd-022-—-science-links-at-most-five-per-panel-curated-per-body-ranked-per-mission" tabindex="-1">UXD-022 — Science links: at most five per panel, curated per body, ranked per mission <a class="header-anchor" href="#uxd-022-—-science-links-at-most-five-per-panel-curated-per-body-ranked-per-mission" aria-label="Permalink to &quot;UXD-022 — Science links: at most five per panel, curated per body, ranked per mission&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-12 (proposed and decided)</li><li><strong>Decider</strong>: the operator, 2026-11-12 — S1, S2 and O6 of <code>docs/wip/2026-11-11-ux-feedback-plan.md</code> (lines 61–62, 177, 445–450), UXD-010, and Q1 to Q10 of <code>docs/wip/2026-11-12-slice-B2-brief.md</code> §9, all &quot;approved as recommended&quot; (the brief&#39;s line &quot;Operator, 2026-11-12: all open questions of §9 (Q1–Q10) approved as recommended&quot;). The number: the brief&#39;s draft was written as UXD-015; that number went to <a href="./UXD-015-flat-chip-row">UXD-015</a> in the meantime, so this record is UXD-022.</li><li><strong>Answers</strong>: S1, S2, O6; slice B2</li><li><strong>Changes</strong>: AGENTS.md (stack table, <code>/science</code> cross-screen chips row); <code>docs/adr/TA.md</code> (the <code>?</code>-chip paragraph); <a href="./../UXS-001">UXS-001</a> detail panel tabs; <a href="./../UXS-014">UXS-014</a> (the ruler paragraph UXD-010 said was missing); Design System §5.3; <a href="./../IA">IA §shell-regions</a>; <code>src/lib/components/README.md</code>; <code>scripts/README.md</code>; <a href="./UXD-010-ruler-regimes-each-get-their-own-science-card">UXD-010</a> (its Verification)</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>At <code>34019040ba8</code> 102 of 289 panels showed more than five science links (mission panels up to 21, every station module the same 11), three planet sections sat on 6 of 8 planet panels, 15 small-body and satellite panels repeated another&#39;s list, four ruler panes repeated a card inside their ruler, and the three per-type default lists (<code>PLANET_</code>, <code>SUN_</code>, <code>SMALL_BODY_SCIENCE_SECTIONS</code>, 21 entries) were dead fallbacks that would have broken the cap had a body ever lacked a list. 108 Serbian list entries pointed at section ids that do not exist (fixed in <code>54975ed8d2d</code> before B2 started; B2 adds the guard).</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><ol><li>A cap in one shared helper, curated lists per body, a ranked pick per mission class, a data test.</li><li>A cap only (slice the first five): the same five sections on every panel of a type.</li><li>Hand-curate every panel: 126 mission lists of science content, which S1 (&quot;need not be complete&quot;) does not ask for.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Option 1. <code>pickScienceLinks</code> (<code>src/lib/science-links.ts</code>) is the one place the cap lives: every list of <code>/science</code> destinations in a panel (counted per distinct destination, at most five) runs through it, the panels and the <code>/explore/&lt;id&gt;</code> entity pages alike. There is no per-type default list: a body without a curated list shows no science block. Lists are curated per body (the locale overlays&#39; <code>science_sections</code>), per station module and Earth object (a <code>science</code> array of <code>tab/section</code> slugs in the base file) and ranked per mission (<code>rankMissionScience</code>: the defining phase the flight data has, a pinned history article where the mission has one, then the mission class&#39;s list, at most three per tab, from language-neutral facts only: destination, crewed, year, and which <code>flight</code> fields exist; never the translated <code>type</code>). Each ruler regime has its own best card and none repeats inside one ruler; across the four rulers a concept may repeat where the physics is the same. The <code>tab</code>/<code>section</code> pair is identical in all 14 locales; only <code>why</code> is translated. Not counted: inline <code>ScienceChip</code>s per field (ADR-036), single contextual links (the ISS 1957 milestone, the station banner&#39;s two links), the Science Lens panel, outbound library links (<code>LearnLink</code>).</p><p>&quot;No two panels of one type with the same list&quot; is strict for bodies (planets, moons, small bodies, belts) and rulers, and for missions, modules and Earth objects the largest group of identical lists is at most a quarter of the family (126 missions: 31; 22 modules: 5; 31 Earth objects: 7). Fleet engines and suits are excluded: every engine illustrates the same two primers.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>One helper, one test file, a mission class table (<code>MISSION_SCIENCE_CLASSES</code>) that doubles as inbound links for the orphan detector, 20 message keys removed (<code>chip_label_*</code> of the module and Earth-object lists and the banner, <code>station_banner_eva_link</code>, <code>belt_science_cta</code>), one rewritten (<code>mp_science_blurb</code>).</li><li>The Belt panel&#39;s raw-path CTA is gone (it linked the same article as its first card).</li><li>Module and Earth-object lists became <code>ScienceCard expanded={false}</code> (title and intro), not one-line links; the station banner keeps two links.</li><li>Planets lost entries where a section sat on more than half of them; the four Trojan <code>why</code> lines (Eurybates, Polymele, Leucus, Orus) moved to <code>orbits/lagrange-points</code>, where they read true; Orus&#39;s <code>why</code> called it a C-type, it is a D-type (the science review caught it; fixed in 14 locales).</li><li>Per-mission pins carry what only some missions earn: the sky crane (Curiosity, Perseverance), the ion drive (Dawn, Psyche, Hayabusa), the Oberth effect (Parker, Solar Orbiter), Lucy&#39;s Trojans, the history articles of Apollo 11 and Sputnik 1. <code>mp_science_blurb</code> reads &quot;Concepts worth knowing for {name}&quot; (not &quot;five&quot;: a list can hold four).</li><li>The family-share threshold (25 %) is a tuning knob in the test.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p><code>src/lib/science-links.test.ts</code> (cap over all 289 panels&#39; data, real sections, body variety, rulers, family share, locale parity, reach), <code>src/lib/science-orphan-detector.test.ts</code> (module, Earth-object and body lists count as inbound links), <code>tests/e2e/science-links-cap.spec.ts</code> on three projects, and <code>node scripts/check-science-links.mjs</code>, which prints <code>B2-CHECK violations: 0</code>.</p>',13)])])}const m=t(a,[["render",n]]);export{u as __pageData,m as default};
